</script>
<svelte:window onkeydown={toolKeys}/>
<svelte:head><title>{ui.text("Editor de escenarios — Isométrico")}</title></svelte:head>
<div class="editor">
 {#if importProgress}<AdventureImportStatus filename={importFilename} progress={importProgress}/>{/if}
 <header class="world-context-header"><a href="/admin" title={ui.text("Volver a mis aventuras")}><ArrowLeft size={18}/><span>{ui.text("Aventuras")}</span></a><strong>{ui.text("Editor de mundo")}</strong><label class="world-adventure-selector"><span>{ui.text("Aventura")}</span><select aria-label={ui.text("Aventura del editor")} value={adventure.id} disabled={saving||openingGame||playerChanging} onchange={e=>switchAdventure(e.currentTarget.value)}>{#each availableAdventures as entry}<option value={entry.id}>{entry.name}</option>{/each}</select></label><div class="file-menu"><button disabled={saving||openingGame} aria-label={ui.text("Más opciones")} aria-expanded={fileMenu} onclick={()=>fileMenu=!fileMenu}><MoreHorizontal size={20}/></button>{#if fileMenu}<div class="file-popover"><button onclick={()=>{fileMenu=false;showTool('adventures');}}><Settings2 size={16}/>{ui.text("Ajustes de la aventura")}</button><button onclick={()=>{fileMenu=false;showTool('maps');}}><Layers size={16}/>{ui.text("Gestionar mapas")}</button><button disabled={transferring||saving||openingGame||!graphicsReady} onclick={()=>{fileMenu=false;fileInput.click();}}><Upload size={16}/>{ui.text("Importar ZIP / JSON")}</button><button onclick={()=>{fileMenu=false;download();}}><Download size={16}/>{ui.text("Exportar ZIP con recursos")}</button><button onclick={()=>openResources()}>{ui.text("Taller de sprites")}</button></div>{/if}</div><input class="sr-only" tabindex="-1" type="file" aria-label={ui.text("Archivo de mapa JSON")} accept=".zip,application/zip,.json,application/json" bind:this={fileInput} onchange={upload}/></header>
 <nav inert={saving||openingGame} class="editor-tools" aria-label={ui.text("Herramientas del editor")}>
  <div class="view-switch" role="group" aria-label={ui.text("Vista del editor")}><button aria-pressed={editorView==='map'} disabled={!graphicsReady} onclick={()=>switchEditorView('map')}><MapIcon size={17}/>{ui.text("Mapa")}</button><button aria-pressed={editorView==='story'} disabled={!graphicsReady} onclick={()=>switchEditorView('story')}><Workflow size={17}/>{ui.text("Guion")}</button></div><span class="tool-divider"></span>
  {#if editorView==='map'}
  <button aria-pressed={!toolPanel&&!panMode&&!brush&&!pendingAsset&&!pendingExit&&!pickingExitId&&!testing} onclick={clearTools}><MousePointer2 size={18}/>{ui.text("Seleccionar")}</button>
  <span class="tool-divider"></span>
  <button aria-pressed={toolPanel==='paint'||!!brush} onclick={()=>showTool('paint')}><Paintbrush size={18}/>{ui.text("Terreno")}</button>
  <button aria-pressed={toolPanel==='catalog'||!!pendingAsset} onclick={()=>showTool('catalog')}><Plus size={18}/>{ui.text("Añadir")}</button>
  <span class="tool-divider"></span>
  <button aria-pressed={toolPanel==='player'} onclick={()=>showTool('player')}><UserRound size={18}/>{ui.text("Jugador")}</button>
  <button aria-pressed={toolPanel==='inventory'} onclick={()=>showTool('inventory')}><Backpack size={18}/>{ui.text("Inventario")}</button>
  <button aria-pressed={toolPanel==='objects'} onclick={()=>showTool('objects')}><List size={18}/>{ui.text("Objetos")}</button>
  {:else}<button disabled={!graphicsReady} onclick={newNarrative}><Clapperboard size={17}/> {ui.text("Añadir evento narrativo")}</button>{/if}
  <button class="inspector-trigger" aria-label={ui.text("Propiedades")} title={ui.text("Inspector")} aria-controls={entity||decoration||mapProperties||narrativeSelection?'world-inspector':'world-tools'} aria-expanded={inspectorVisible||activeToolPanel==='adventures'||activeToolPanel==='paint'&&!!(selectedTerrain||selectedWall)} onclick={toggleInspector}><Settings2 size={18}/><span class="trigger-label">{ui.text("Propiedades")}</span></button>
 </nav>
 <div class="editor-body" class:compact={compactEditor} bind:this={editorBody} inert={saving||openingGame}>
  {#if activeToolPanel}<EditorPanel id="world-tools" title={activeToolPanel==='player'?ui.text("Personaje principal"):activeToolPanel==='inventory'?ui.text("Inventario de la aventura"):activeToolPanel==='adventures'?ui.text("Aventuras"):activeToolPanel==='maps'?ui.text("Mapas de la aventura"):activeToolPanel==='objects'?ui.text("Objetos del mapa"):activeToolPanel==='catalog'?ui.text("Catálogo de recursos"):selectedTerrain?ui.text("Propiedades del suelo"):selectedWall&&!wallTool?ui.text(selectedWall.kind==='door'?"Propiedades de la puerta":selectedWall.kind==='railing'?"Propiedades de la baranda":"Propiedades de la pared"):ui.text("Suelo y construcción")} subtitle={adventure.name} side="right" width={320} dockedWidth={320} open inflow onclose={closeToolPanel}>

   <div class="world-tool-content"><div>
   {#if activeToolPanel==='player'}
    <p class="environment-note">{ui.text("Elige el personaje que controlarás en todos los mapas de esta aventura.")}</p>
    <label>{ui.text("Personaje principal")}<select aria-label={ui.text("Personaje principal")} value={graphics.activePlayer??'default'} disabled={playerChanging||!graphicsReady} onchange={e=>chooseMainPlayer(e.currentTarget.value)}><option value="default">{ui.text("Explorador original")}</option>{#each Object.entries(graphics.players??{}) as [id,player]}<option value={id}>{player.name}</option>{/each}</select></label>
    <p class="environment-note">{playerChanging?ui.text("Actualizando personaje…"):ui.text("La selección se guarda automáticamente en este navegador.")}</p>
    {#if !Object.keys(graphics.players??{}).length}<p class="environment-note">{ui.text("Aún no hay jugadores propios guardados. Importa el ZIP de tu personaje en el taller para añadirlo aquí.")}</p>{/if}
    <button class="panel-primary" disabled={playerChanging} onclick={refreshPlayers}>{ui.text("Actualizar jugadores")}</button>
    <button class="panel-primary" disabled={playerChanging} onclick={()=>openResources('player')}>{ui.text("Importar o gestionar jugadores")}</button>
   {:else if activeToolPanel==='inventory'}
    <p class="environment-note">{ui.text("Artículos compartidos por todos los mapas. Asígnalos a objetos recogibles desde sus propiedades.")}</p>
    <button class="panel-primary" onclick={addInventoryArticle}><Plus size={16}/> {ui.text("Nuevo artículo")}</button>
    <label>{ui.text("Artículo")}<select bind:value={inventorySelection}><option value="">{ui.text("Seleccionar…")}</option>{#each adventure.items??[] as item}<option value={item.id}>{item.name}</option>{/each}</select></label>
    {#if inventoryArticle}<label>{ui.text("Nombre")}<input value={inventoryArticle.name} onchange={e=>{if(e.currentTarget.value.trim())editInventoryArticle({name:e.currentTarget.value.trim()});}}/></label>
    <label>{ui.text("Descripción")}<input value={inventoryArticle.description} onchange={e=>editInventoryArticle({description:e.currentTarget.value})}/></label>
    <label class="checkbox"><input type="checkbox" checked={inventoryArticle.stackable} onchange={e=>editInventoryArticle({stackable:e.currentTarget.checked})}/> {ui.text("Apilable")}</label>
    <button class="delete-object" disabled={inventoryInUse(inventoryArticle.id)} onclick={removeInventoryArticle}><Trash2 size={16}/> {ui.text("Eliminar artículo")}</button>
    {#if inventoryInUse(inventoryArticle.id)}<p class="environment-note">{ui.text("Este artículo está vinculado a objetos o condiciones. Desvincúlalo antes de eliminarlo.")}</p>{/if}
    {:else}<p class="environment-note">{ui.text("Selecciona un artículo o crea uno nuevo.")}</p>{/if}
   {:else if activeToolPanel==='adventures'}<label>{ui.text("Aventura")}<select value={adventure.id} onchange={e=>switchAdventure(e.currentTarget.value)}>{#each availableAdventures as item}<option value={item.id}>{item.id===adventure.id?adventure.name:item.name}</option>{/each}</select></label><label>{ui.text("Nombre de la aventura")}<input value={adventure.name} onchange={e=>{snapshot();adventure={...adventure,name:e.currentTarget.value};}}/></label><AdventureLanguages value={adventure.localization} onchange={localization=>{snapshot();adventure={...adventure,localization};}}/><p class="environment-note">{adventure.maps.length} {ui.text("mapas en esta aventura. Al cambiar de aventura se guardan tus cambios.")}</p><button class="panel-primary" onclick={newAdventure}>{ui.text("Nueva aventura")}</button><button class="panel-primary" onclick={duplicateAdventure}>{ui.text("Duplicar aventura")}</button><button class="panel-primary" onclick={()=>openResources()}>{ui.text("Gestionar recursos")}</button><button class="panel-primary" onclick={()=>showTool('maps')}>{ui.text("Gestionar mapas de esta aventura")}</button><AdventureTranslations adventure={bundle()} onchange={(next,checkpoint)=>{if(checkpoint)snapshot();adventure={...adventure,localization:next.localization};}}/><section class="adventure-transfer" aria-label={ui.text("Importar y exportar aventuras")}><h3>{ui.text("Importar y exportar")}</h3><div class="paint-actions"><button disabled={transferring} onclick={download}><Download size={16}/> {ui.text("Exportar ZIP con recursos")}</button><button disabled={transferring||saving||openingGame||!graphicsReady} onclick={()=>adventureFileInput?.click()}><Upload size={16}/> {ui.text("Importar aventura")}</button></div><input class="sr-only" tabindex="-1" type="file" aria-label={ui.text("Archivo ZIP o JSON de aventura")} accept=".zip,application/zip,.json,application/json" bind:this={adventureFileInput} onchange={e=>upload(e,true)}/></section>
   {:else if activeToolPanel==='maps'}<label for="template">{ui.text("Mapas ·")} {adventure.maps.length}</label><select id="template" value={draft.id} onchange={e=>changeWorld(e.currentTarget.value)}>{#each adventure.maps as map}<option value={map.id}>{map.id===draft.id?draft.name:map.name}{map.id===adventure.startMap?' · Inicio':''}</option>{/each}</select><div class="paint-actions"><button onclick={()=>newMap()}>{ui.text("+ Nuevo mapa")}</button><button onclick={()=>newMap(true)}>{ui.text("Duplicar")}</button><button disabled={adventure.startMap===draft.id} onclick={()=>{snapshot();adventure={...adventure,startMap:draft.id};}}>{ui.text("Empezar aquí")}</button></div><button class="panel-primary" onclick={showMapProperties}>{ui.text("Propiedades del mapa actual")}</button>
   {:else if activeToolPanel==='objects'}<label class="search-label"><Search size={16}/><input aria-label={ui.text("Buscar objetos")} placeholder={ui.text("Buscar objeto…")} bind:value={search}/></label><div class="object-list">{#each draft.entities.filter(e=>e.label.toLocaleLowerCase().includes(search.toLocaleLowerCase())) as e}<button onclick={()=>selectObject(e.id)}><span>{e.label}</span><small>{e.position.x}, {e.position.y}</small></button>{:else}<p class="environment-note">{ui.text("No hay objetos que coincidan.")}</p>{/each}</div>
   {:else if activeToolPanel==='catalog'}<label>{ui.text('Colocar como')}<select aria-label={ui.text('Colocar como')} bind:value={placementMode} onchange={()=>{pendingAsset=null;}}><option value="object">{ui.text('Objeto del mapa')}</option><option value="decoration">{ui.text('Decorado exterior')}</option></select></label>{#if draft.decorations?.length}<section aria-label={ui.text('Decorados exteriores')}><h3>{ui.text('Decorados exteriores')}</h3>{#each draft.decorations as d}<button class="panel-primary" onclick={()=>selectObject(d.id)}>{d.label}</button>{/each}</section>{/if}<AdventureResourceCatalog entries={catalogEntries} kind={catalogKind} kinds={['object','npc']} onkindchange={next=>{catalogKind=next;catalogCategory='all';}} bind:query={catalogSearch} bind:category={catalogCategory} objectFamilies={graphics.objectFamilies??{}} selected={pendingAsset??''} resolve={url=>url} onselect={beginPlacement}/><p class="environment-note">{ui.text("Elige un gráfico y pulsa sobre el mapa para colocarlo. Organiza las familias en el taller de sprites.")}</p><button class="panel-primary" onclick={()=>openResources()}><Pencil size={15}/> {ui.text("Abrir taller de sprites")}</button>
   {:else if activeToolPanel==='paint'}   {#if selectedTerrain}<section class="selected-floor-properties" aria-label={ui.text("Propiedades del suelo")}><p class="environment-note">{ui.text("Casilla seleccionada")} · {selectedTerrain.x}, {selectedTerrain.y}</p><label>{ui.text("Suelo")}<select aria-label={ui.text("Suelo de la casilla")} value={terrainAt(draft,selectedTerrain)?`terrain:${terrainAt(draft,selectedTerrain)}`:tileAt(draft,selectedTerrain)} onchange={event=>updateTerrain(event.currentTarget.value as MapBrush)}>{#each Object.entries(graphics.tileFamilies??{}) as [id,family]}<option value={`terrain:${id}`}>{family.name} · {ui.text("Automático")}</option>{/each}{#each tileChoices as tile}<option value={tile.id}>{tile.label}</option>{/each}</select></label><label>{ui.text("Altura")}<input aria-label={ui.text("Altura de la casilla")} type="number" min="-2" max="2" step="1" value={levelAt(draft,selectedTerrain)} onchange={event=>{const value=event.currentTarget.valueAsNumber;if(Number.isInteger(value))updateTerrain(`height:${value}`);}}/></label><label>{ui.text("Escaleras")}<select aria-label={ui.text("Escalera de la casilla")} value={stairAt(draft,selectedTerrain)??''} onchange={event=>updateTerrain(event.currentTarget.value?`stairs:${event.currentTarget.value as Facing}`:'stairs:erase')}><option value="">{ui.text("Ninguno")}</option>{#each [['ne','Noreste'],['se','Sureste'],['sw','Suroeste'],['nw','Noroeste']] as [value,label]}<option {value}>{ui.text(label)}</option>{/each}</select></label><p class="environment-note">{ui.text("Estos cambios afectan solo a la casilla seleccionada.")}</p><button class="panel-primary" onclick={()=>{selectedTerrain=null;mapMode='tiles';}}><Paintbrush size={16}/>{ui.text("Pintar terreno")}</button></section>{:else if selectedWall&&!wallTool}<section class="selected-wall-properties" aria-label={ui.text(selectedWall.kind==='door'?"Propiedades de la puerta":selectedWall.kind==='railing'?"Propiedades de la baranda":"Propiedades de la pared")}>
 {#if selectedWall}<p>{selectedWall.kind==='door'?ui.text("Puerta"):selectedWall.kind==='railing'?ui.text("Baranda"):ui.text("Pared")} · {selectedWall.x}, {selectedWall.y}</p>{#if selectedWall.kind==='door'}{#if selectedWall.exitId}<button class="panel-primary" onclick={()=>selectObject(selectedWall!.exitId!)}>{ui.text("Editar destino")}</button><button class="panel-primary" onclick={unlinkDoor}>{ui.text("Desvincular puerta")}</button>{:else}<label>{ui.text("Conectar puerta con")}<select bind:value={destination}><option value="">{ui.text("Elegir destino…")}</option>{#each adventure.maps.filter(m=>m.id!==draft.id) as m}<option value={m.id}>{m.name}</option>{/each}</select></label><button class="panel-primary" disabled={!destination} onclick={linkDoor}>{ui.text("Conectar puerta")}</button>{/if}{/if}{/if}{#if selectedWall.kind==='wall'}<p>{ui.text("Acabado")}</p><div class="wall-materials">{#each wallMaterials as material}<button aria-pressed={wallMaterial===material.id} onclick={()=>chooseWallMaterial(material.id)}><span class={`material-swatch ${material.id}`}></span>{ui.text(material.label)}</button>{/each}</div>{/if}{#if selectedWall.kind==='railing'}<RailingPalette {graphics} style={railingStyle} family={railingFamily} variant={railingVariant} selected={!!selectedWall} onchoose={chooseRailing} onvariant={chooseRailingVariant} onedit={id=>void openResources('railing',id)}/>{/if}<label>{ui.text("Opacidad de paredes y barandas")}<input type="range" min="0.15" max="1" step="0.05" bind:value={wallOpacity}/></label><button class="panel-primary" onclick={()=>{mapMode=selectedWall?.kind==='railing'?'railing':'wall';selectedWall=null;}}><Paintbrush size={16}/>{ui.text("Pintar terreno")}</button></section>{:else}<section class="tile-palette" aria-label={ui.text("Editar terreno")}><div class="paint-actions map-tabs">{#each [['tiles','Baldosas'],['wall','Paredes'],['door','Puertas'],['railing','Barandas'],['levels','Niveles']] as [id,label]}<button aria-pressed={mapMode===id} onclick={()=>{mapMode=id as 'tiles'|'wall'|'door'|'railing'|'levels';brush=null;wallTool=id==='wall'||id==='door'||id==='railing'?id:null;selectedWall=null;selectedTerrain=null;}}>{ui.text(label??'')}</button>{/each}</div>{#if mapMode==='tiles'}<h3>{ui.text("Baldosas")}</h3><p>{ui.text("Elige un suelo o una familia y pinta sobre el mapa.")}</p><MapTerrainPalette {graphics} {brush} selectedFamily={terrainFamilyViews[adventure.id]??null} onfamilychange={id=>terrainFamilyViews[adventure.id]=id} onchoose={chooseTerrainBrush} onedit={tile=>void openResources('tile',tile)}/><button class="panel-primary" onclick={()=>openResources('tile')}><Plus size={15}/> {ui.text("Añadir suelos en el taller")}</button><div class="paint-actions"><button aria-pressed={brush==='erase'} onclick={()=>{wallTool=null;brush='erase';testing=false;}}>{ui.text("Restaurar suelo")}</button><button disabled={brush===null} onclick={()=>{brush=null;notice='Pincel desactivado.';}}>{ui.text("Dejar de pintar")}</button></div><p>{brush===null?ui.text("Pincel desactivado"):brush==='erase'?ui.text("Restaurar: recupera el suelo original de cada casilla."):brush==='void'?ui.text("Vacío: elimina casillas libres. Mueve primero los objetos y accesos."):ui.text("Pincel activo. Puedes pintar también debajo de los objetos.")} {ui.text("Las casillas vacías no se pueden atravesar.")}</p>
 {:else if mapMode==='levels'}<h3>{ui.text("Altura")}</h3><div class="stair-options level-options" role="group" aria-label={ui.text("Altura del terreno")}>{#each [-2,-1,0,1,2] as level}<button aria-label={ui.text("Pintar nivel {arg0}",{arg0:level})} title={level===0?ui.text("Nivel 0 · Base"):ui.text("Nivel {arg0}{arg1}",{arg0:level>0?'+':'',arg1:level})} aria-pressed={brush===`height:${level}`} onclick={()=>{brush=`height:${level}`;wallTool=null;}}><img src={`/editor/level-${level}.svg`} alt=""/><span>{level>0?'+':''}{level}</span></button>{/each}</div>
 <h3>{ui.text("Escaleras")}</h3><div class="stair-options" role="group" aria-label={ui.text("Orientación de escaleras")}>{#each [['se','Sureste'],['sw','Suroeste'],['nw','Noroeste'],['ne','Noreste']] as [direction,label]}<button aria-label={ui.text("Escalera hacia {arg0}",{arg0:label.toLowerCase()})} title={ui.text("Subir hacia {arg0}",{arg0:label.toLowerCase()})} aria-pressed={brush===`stairs:${direction}`} onclick={()=>{brush=`stairs:${direction}` as MapBrush;wallTool=null;}}><img src={`/editor/stairs-${direction}.svg`} alt=""/></button>{/each}<button class="erase-stairs" aria-label={ui.text("Eliminar escalera")} title={ui.text("Eliminar escalera")} aria-pressed={brush==='stairs:erase'} onclick={()=>{brush='stairs:erase';wallTool=null;}}><X size={22}/></button></div>
 {:else}<h3>{mapMode==='wall'?ui.text("Paredes"):mapMode==='railing'?ui.text("Barandas"):ui.text("Puertas")}</h3><p>{mapMode==='railing'?ui.text("Pulsa un borde del suelo para colocar una baranda."):ui.text("Pulsa cerca de un borde del suelo. Para puertas, elige un tramo de pared existente.")}</p><div class="paint-actions">{#each (mapMode==='wall'?[['wall','Pared'],['remove','Borrar pared']]:mapMode==='railing'?[['railing','Baranda'],['remove','Borrar baranda']]:[['door','Puerta']]) as [id,label]}<button aria-pressed={wallTool===id} onclick={()=>{brush=null;wallTool=id as 'wall'|'door'|'railing'|'remove';selectedWall=null;selectedTerrain=null;}}>{ui.text(label??'')}</button>{/each}<button onclick={()=>{wallTool=null;brush=null;}}>{ui.text("Seleccionar borde")}</button></div>
 {#if mapMode==='railing'}<RailingPalette {graphics} style={railingStyle} family={railingFamily} variant={railingVariant} selected={!!selectedWall} onchoose={chooseRailing} onvariant={chooseRailingVariant} onedit={id=>void openResources('railing',id)}/>{/if}
 {#if mapMode==='wall'}<p id="wall-finish-label">{ui.text("Acabado")}</p><div class="wall-materials" role="group" aria-labelledby="wall-finish-label">{#each wallMaterials as material}<button aria-pressed={wallMaterial===material.id} onclick={()=>chooseWallMaterial(material.id)}><span class={`material-swatch ${material.id}`}></span>{ui.text(material.label??'')}</button>{/each}</div>{/if}
 <label>{ui.text("Opacidad de paredes y barandas")}<input type="range" min="0.15" max="1" step="0.05" bind:value={wallOpacity}/></label>
 {#if selectedWall}<p>{selectedWall.kind==='door'?ui.text("Puerta"):selectedWall.kind==='railing'?ui.text("Baranda"):ui.text("Pared")} · {selectedWall.x}, {selectedWall.y}</p>{#if selectedWall.kind==='door'}{#if selectedWall.exitId}<button class="panel-primary" onclick={()=>selectObject(selectedWall!.exitId!)}>{ui.text("Editar destino")}</button><button class="panel-primary" onclick={unlinkDoor}>{ui.text("Desvincular puerta")}</button>{:else}<label>{ui.text("Conectar puerta con")}<select bind:value={destination}><option value="">{ui.text("Elegir destino…")}</option>{#each adventure.maps.filter(m=>m.id!==draft.id) as m}<option value={m.id}>{m.name}</option>{/each}</select></label><button class="panel-primary" disabled={!destination} onclick={linkDoor}>{ui.text("Conectar puerta")}</button>{/if}{/if}{/if}
 {/if}</section>{/if}{/if}
</div></div>
  </EditorPanel>{/if}
  <main class="editor-preview" class:with-inspector={!!entity&&!testing&&!pickingExitId}>{#if editorView==='story'}{#key adventure.id}<StoryBoard adventure={bundle()} {graphics} selected={narrativeSelection?eventNode(narrativeSelection):selected?objectNode({mapId:draft.id,entityId:selected}):mapProperties?mapNode(draft.id):''} onselect={openBoardSelection} onlayout={boardLayout}/>{/key}{:else}<div class="editor-canvas" bind:this={canvasHost}><div class="map-heading"><h1><button onclick={showMapProperties} title={ui.text("Propiedades del mapa")}>{preview.name}</button></h1></div>{#if graphicsReady}<World {revision} {panMode} {graphics} {adapter} editor={editing} onready={ready} onstatus={s=>notice=s}/>{:else}<div class="preload-stage">{#if loadFailed}<p role="alert">{ui.text(error)}</p><button onclick={initialize}>{ui.text("Reintentar carga")}</button>{:else}<LoadProgress progress={loadProgress}/>{/if}</div>{/if}<MapDissolve image={transitionImage} ready={transitionReady} ondone={()=>transitionImage=null}/></div><div class="editor-feedback">{#if pendingExit}<p>{ui.text("Salida hacia {arg0}: selecciona una casilla libre.",{arg0:adventure.maps.find(m=>m.id===destination)?.name??''})} <button onclick={cancelExitPlacement}>{ui.text("Cancelar")}</button></p>{:else if pendingAsset}<p>{#if placementMode==='decoration'}{ui.text('Pulsa la cuadrícula, dentro o fuera del suelo, para colocar el decorado.')}{:else}{ui.text('Pulsa una casilla para colocar')} {ui.text('el objeto')}.{/if} <button onclick={clearTools}>{ui.text("Cancelar")}</button></p>{/if}{#if pickingExitId}<p>{ui.text("Selecciona una casilla libre en este mapa.")} <button onclick={cancelPicking}>{ui.text("Cancelar selección")}</button></p>{/if}{#if error}<p role="alert" class="editor-error">{ui.text(error)}</p>{:else}<p role="status">{ui.text(notice)}</p>{/if}<small>{ui.text("Mano: desplazar vista. También espacio + arrastre o botón central. Selecciona y arrastra con ratón o dedo, o mueve con las flechas de la cuadrícula. Guardar y jugar aplica el mapa en este navegador. Exporta el JSON como copia.")}</small></div>{/if}</main>
  {#if inspectorVisible&&narrativeSelection&&narrativeEvent(bundle(),narrativeSelection)}{@const event=narrativeEvent(bundle(),narrativeSelection)!}<aside id="world-inspector" class="editor-inspector entity-drawer" aria-label={ui.text("Inspector del evento narrativo")}><div class="inspector-main" inert={!!chatEditing}><div class="panel-heading"><h2>{event.name}</h2><button aria-label={ui.text("Cerrar inspector del evento")} onclick={closeInspector}><X size={18}/></button></div><div class="inspector-body"><NarrativeEventEditor adventure={bundle()} {event} onchange={editNarrative} onchat={id=>void openNarrativeChat(id)} onremove={removeNarrative}/></div></div>{#if chatEditing}<section class="module-layer" aria-label={ui.text("Editar módulo del evento")}><ContentModuleEditor locales={adventure.localization?.locales??[adventure.localization?.defaultLocale??'es']} baseLocale={adventure.localization?.defaultLocale??'es'} module={chatEditing.module} chat={chatEditing.chat} title={chatEditing.title} uses={chatEditing.uses} onapply={applyContentModule} onclose={()=>void closeChatLayer()} ondirty={value=>chatDirty=value}/></section>{/if}</aside>{/if}
  {#if inspectorVisible&&(entity||decoration||mapProperties)}{#key mapProperties}<aside id="world-inspector" class="editor-inspector" class:entity-drawer={!!entity&&!mapProperties} class:map-properties={mapProperties} aria-label={ui.text("Inspector")}><div class="inspector-main" inert={!!chatEditing} aria-hidden={chatEditing?true:undefined}><div class="panel-heading"><h2>{selected===null?ui.text("Propiedades del mapa"):entity?.label??decoration?.label}</h2><div class="panel-actions"><button aria-label={ui.text("Cerrar inspector")} onclick={closeInspector}><X size={18}/></button></div></div><div class="inspector-body">
   {#if decoration}<DecorationInspector value={decoration} picking={!!decorationHeightId} onchange={editDecoration} onheight={()=>{decorationHeightId=decorationHeightId?null:decoration.id;notice='Pulsa una casilla del terreno para tomar su altura.';}} onremove={removeDecoration}/><button class="panel-primary" disabled={saving||openingGame||playerChanging||!graphicsReady} onclick={()=>openResources('object',decoration.visualId,false)}><Pencil size={15}/> {ui.text('Editar sprite')}</button>
   {:else if selected===null}
   <div class="map-adventure-context"><div><small>{ui.text("Aventura")}</small><strong>{adventure.name}</strong></div><button aria-label={ui.text("Ajustes de la aventura")} title={ui.text("Ajustes de la aventura")} onclick={()=>showTool('adventures')}><Settings2 size={19}/></button></div>
   <label for="mapname">{ui.text("Nombre del mapa")}</label><input id="mapname" value={draft.name} onchange={e=>{snapshot();draft={...draft,name:e.currentTarget.value};}}/>
   <section class="map-dimensions" aria-label={ui.text("Dimensiones del mapa")}><div class="dimensions-heading"><h3>{ui.text("Dimensiones del mapa")}</h3><small>{draft.width} × {draft.height} {ui.text("casillas")}</small></div><div class="pair"><label>{ui.text("Ancho")}<input type="number" min="1" max="64" value={draft.width} onchange={e=>{snapshot();draft=resizeMapWalls(draft,+e.currentTarget.value,draft.height);}}/></label><label>{ui.text("Alto")}<input type="number" min="1" max="64" value={draft.height} onchange={e=>{snapshot();draft=resizeMapWalls(draft,draft.width,+e.currentTarget.value);}}/></label></div></section>
   <MapExitControls adventure={bundle()} mapId={draft.id} bind:destination bind:expanded={exitComposer} onopen={openExitComposer} onplace={beginExitPlacement} oncreate={createExitDestination} onselect={selectObject}/>
   <MapAppearance value={draft} {graphics} onchange={updateMapAppearance}/>

   <div class="pair"><label>{ui.text("Entrada X")}<input type="number" min="0" value={draft.spawn.x} onchange={e=>{snapshot();draft={...draft,spawn:{...draft.spawn,x:+e.currentTarget.value}};}}/></label><label>{ui.text("Entrada Y")}<input type="number" min="0" value={draft.spawn.y} onchange={e=>{snapshot();draft={...draft,spawn:{...draft.spawn,y:+e.currentTarget.value}};}}/></label></div>


   <button class="panel-primary" onclick={()=>showTool('maps')}><Layers size={16}/> {ui.text("Gestionar mapas")}</button>

   {:else if entity}<div class="inspector-tabs" role="group" aria-label={ui.text("Secciones del elemento")}><button aria-pressed={inspectorTab==='properties'} onclick={()=>inspectorTab='properties'}>{ui.text("Propiedades")}</button><button aria-pressed={inspectorTab==='modules'} onclick={()=>inspectorTab='modules'}>{ui.text("Módulos")}</button><button aria-pressed={inspectorTab==='conditions'} onclick={()=>inspectorTab='conditions'}>{ui.text("Condiciones")}</button></div><div hidden={inspectorTab!=='conditions'}><BehaviorEditor adventure={bundle()} ref={{mapId:draft.id,entityId:entity.id}} {graphics} onchange={editBehavior} onprepare={addOpenClosed}/></div><div hidden={inspectorTab!=='modules'}>{#if selectedExit||entity.pickup}<p class="environment-note">{ui.text("Este elemento utiliza su acción para viajar o recoger un artículo. Puedes añadir módulos a los demás objetos y personajes.")}</p>{:else}
    <ModuleSequenceEditor adventure={bundle()} modules={entityModules} sequence={behavior(bundle(),{mapId:draft.id,entityId:entity.id})?.moduleSequence} loading={chatLoading} onedit={editContentModule} onchange={updateObjectSequence}/>{/if}</div><div hidden={inspectorTab!=='properties'}><label for="entityname">{ui.text("Nombre del objeto")}</label><input id="entityname" value={entity.label} onchange={e=>update({label:e.currentTarget.value})}/><label>{ui.text("Descripción")}<input value={entity.description??''} onchange={e=>update({description:e.currentTarget.value})}/></label>{#if selectedExit}<p class="environment-note">{draft.walls?.some(w=>w.exitId===entity.id)?ui.text("Puerta conectada a otro mapa."):ui.text("Loseta de salida con flecha hacia el borde más cercano.")}</p>{:else if visualCatalog.filter(a=>compatibleVisualKind(entity.kind,a.kind)).length>1}<label>{ui.text("Gráfico")}<select value={entity.visualId??`pixel.${entity.kind}`} onchange={e=>{const asset=visualCatalog.find(a=>a.id===e.currentTarget.value)!;update({visualId:asset.id,...(asset.color!==undefined?{color:asset.color}:{})});}}>{#each visualCatalog.filter(a=>compatibleVisualKind(entity.kind,a.kind)) as asset}<option value={asset.id}>{asset.label}</option>{/each}</select></label>{/if}{#if !selectedExit}<button class="panel-primary" disabled={saving||openingGame||playerChanging||!graphicsReady} onclick={()=>openResources(entity.kind==='person'?'npc':'object',entity.visualId??`pixel.${entity.kind}`,false)}><Pencil size={15}/> {ui.text('Editar sprite')}</button>{/if}<button class="flip-button" aria-pressed={entity.flipX??false} onclick={flip}>{ui.text("↔ Voltear horizontalmente")}</button><small>{entity.flipX?ui.text("Orientación reflejada"):ui.text("Orientación original")}</small><small class="asset-id">{selectedExit?(draft.walls?.some(w=>w.exitId===entity.id)?ui.text("Puerta de salida"):ui.text("Loseta de salida")):entity.visualId??`pixel.${entity.kind}`}</small>
    {#if !selectedExit}<label>{ui.text("Objeto de inventario")}<select value={entity.pickup?.itemId??''} onchange={e=>{const id=e.currentTarget.value;update(id?{pickup:{itemId:id,quantity:1},solid:false,interaction:{label:'Recoger',action:'inventory.collect',resourceId:id}}:{pickup:undefined,interaction:undefined});}}><option value="">{ui.text("No es recogible")}</option>{#each adventure.items??[] as item}<option value={item.id}>{item.name}</option>{/each}</select></label>
    <button onclick={()=>{inventorySelection=entity?.pickup?.itemId??'';showTool('inventory');}}>{ui.text("Gestionar artículos")}</button>
    {#if entity.pickup}<label>{ui.text("Cantidad")}<input type="number" min="1" step="1" value={entity.pickup.quantity} onchange={e=>update({pickup:{...entity!.pickup!,quantity:Math.max(1,Math.floor(+e.currentTarget.value)||1)}})}/></label>{/if}{/if}
    <details class="advanced"><summary>{ui.text("Posición, tamaño y colisiones")}</summary>    <div class="pair"><label>{ui.text("Posición X")}<input type="number" min="0" value={entity.position.x} onchange={e=>entityDimension('position','x',e.currentTarget)}/></label><label>{ui.text("Posición Y")}<input type="number" min="0" value={entity.position.y} onchange={e=>entityDimension('position','y',e.currentTarget)}/></label></div>
    <div class="pair"><label>{ui.text("Anchura")}<input type="number" min="1" value={entity.size?.x??1} onchange={e=>entityDimension('size','x',e.currentTarget)}/></label><label>{ui.text("Profundidad")}<input type="number" min="1" value={entity.size?.y??1} onchange={e=>entityDimension('size','y',e.currentTarget)}/></label></div>
    <label class="checkbox"><input type="checkbox" checked={entity.solid!==false} onchange={e=>{update({solid:e.currentTarget.checked});e.currentTarget.checked=entity?.solid!==false;}}/> {ui.text("Bloquea el paso")}</label>
</details>
    {#if selectedExit}<section aria-label={ui.text("Destino de la salida")}><h3>{ui.text("Salida a otro mapa")}</h3><label>{ui.text("Artículo necesario")}<select value={selectedExit.requirement?.itemId??''} onchange={e=>editExit({requirement:e.currentTarget.value?{itemId:e.currentTarget.value,quantity:1,consume:false}:undefined})}><option value="">{ui.text("Ninguno")}</option>{#each adventure.items??[] as item}<option value={item.id}>{item.name}</option>{/each}</select></label>{#if selectedExit.requirement}<label>{ui.text("Cantidad requerida")}<input type="number" min="1" step="1" value={selectedExit.requirement.quantity} onchange={e=>editExit({requirement:{...selectedExit!.requirement!,quantity:Math.max(1,Math.floor(+e.currentTarget.value)||1)}})}/></label><label class="checkbox"><input type="checkbox" checked={selectedExit.requirement.consume} onchange={e=>editExit({requirement:{...selectedExit!.requirement!,consume:e.currentTarget.checked}})}/> {ui.text("Consumir al desbloquear")}</label>{/if}<label>{ui.text("Mapa destino")}<select value={selectedExit.toMap} onchange={e=>{const map=adventure.maps.find(m=>m.id===e.currentTarget.value)!;editExit({toMap:map.id,arrival:map.spawn,destinationEntityId:undefined});}}>{#each adventure.maps as map}<option value={map.id}>{map.name}</option>{/each}</select></label><div class="pair"><label>{ui.text("Llegada X")}<input type="number" min="0" value={selectedExit.arrival.x} onchange={e=>editExit({arrival:{...selectedExit!.arrival,x:+e.currentTarget.value}})}/></label><label>{ui.text("Llegada Y")}<input type="number" min="0" value={selectedExit.arrival.y} onchange={e=>editExit({arrival:{...selectedExit!.arrival,y:+e.currentTarget.value}})}/></label></div><p class="environment-note">{ui.text("Si existe una salida de vuelta, aparecerás sobre su baldosa mirando hacia el interior. Estas coordenadas se usan cuando no hay una entrada vinculada.")}</p><div class="paint-actions"><button onclick={chooseArrival}>{ui.text("Elegir llegada en el mapa")}</button><button onclick={returnExit}>{ui.text("Crear conexión de vuelta")}</button><button onclick={()=>changeWorld(selectedExit!.toMap)}>{ui.text("Editar mapa destino")}</button></div></section>{:else}
    <details class="advanced"><summary>{ui.text("Interacción y acciones")}</summary><label class="checkbox"><input type="checkbox" checked={!!entity.interaction} onchange={e=>update({interaction:e.currentTarget.checked?{label:'Abrir',action:'space.open',resourceId:'world'}:undefined})}/> {ui.text("Tiene interacción")}</label>
    {#if entity.interaction}<label>{ui.text("Texto de la interacción")}<input value={entity.interaction.label} onchange={e=>setInteraction('label',e.currentTarget.value)}/></label><label>{ui.text("Acción del anfitrión")}<input value={entity.interaction.action} onchange={e=>setInteraction('action',e.currentTarget.value)}/></label><label>{ui.text("Recurso asociado")}<input value={entity.interaction.resourceId} onchange={e=>setInteraction('resourceId',e.currentTarget.value)}/></label>{/if}
    </details>{/if}
    {#if entity.kind==='desk'||entity.seat}<details class="advanced"><summary>{ui.text("Asiento y orientación")}</summary>
    {#if entity.kind==='desk'}<label class="checkbox"><input type="checkbox" checked={!!entity.seat} onchange={e=>update({seat:e.currentTarget.checked?{cell:{x:entity!.position.x,y:entity!.position.y+(entity!.size?.y??1)},facing:'ne'}:undefined,interactionPoints:undefined})}/> {ui.text("Puesto con asiento")}</label>{/if}
    {#if entity.seat}<div class="pair"><label>{ui.text("Asiento X")}<input type="number" min="0" value={entity.seat.cell.x} onchange={e=>setSeat('x',+e.currentTarget.value)}/></label><label>{ui.text("Asiento Y")}<input type="number" min="0" value={entity.seat.cell.y} onchange={e=>setSeat('y',+e.currentTarget.value)}/></label></div><label>{ui.text("Orientación del asiento")}<select value={entity.seat.facing} onchange={e=>update({seat:{...entity!.seat!,facing:e.currentTarget.value as Facing}})}><option value="ne">{ui.text("Noreste")}</option><option value="se">{ui.text("Sureste")}</option><option value="sw">{ui.text("Suroeste")}</option><option value="nw">{ui.text("Noroeste")}</option></select></label>{/if}
    </details>{/if}
    <button class="delete-object" onclick={()=>{if(leaveChat())remove();}}><Trash2 size={16}/> {ui.text("Eliminar objeto")}</button></div>
   {/if}
  </div></div>
  {#if chatEditing}<section class="module-layer" transition:fly={{x:24,duration:160}} aria-label={ui.text("Editar módulo del objeto")}><ContentModuleEditor locales={adventure.localization?.locales??[adventure.localization?.defaultLocale??'es']} baseLocale={adventure.localization?.defaultLocale??'es'} module={chatEditing.module} chat={chatEditing.chat} title={chatEditing.title} uses={chatEditing.uses} onapply={applyContentModule} onclose={()=>void closeChatLayer()} ondirty={value=>chatDirty=value}/></section>{/if}
  </aside>{/key}{/if}
 </div>
 <footer class="world-footer">{#if editorView==='story'&&error}<span class="story-error" role="alert">{ui.text(error)}</span>{/if}<span class="world-save-status" role="status">{saving?ui.text("Guardando…"):hasChanges?ui.text("Cambios sin guardar"):ui.text("Guardado")}</span><div class="quick-map" role="group" aria-label={ui.text("Mapa actual")}><Layers size={18}/><select aria-label={ui.text("Seleccionar mapa")} value={draft.id} onchange={e=>changeWorld(e.currentTarget.value)}>{#each adventure.maps as map}<option value={map.id}>{map.id===draft.id?draft.name:map.name}{map.id===adventure.startMap?' · Inicio':''}</option>{/each}</select><button aria-label={ui.text("Propiedades del mapa actual")} title={ui.text("Propiedades del mapa actual")} aria-expanded={mapProperties&&inspectorVisible} onclick={showMapProperties}><Settings2 size={19}/></button></div>{#if editorView==='map'}<div class="editor-zoom" role="group" aria-label={ui.text("Controles del mapa")}><button aria-label={ui.text("Deshacer")} title={ui.text("Deshacer (Ctrl/⌘ Z)")} disabled={!history.length} onclick={undo}><Undo2 size={17}/></button><button aria-label={ui.text("Rehacer")} title={ui.text("Rehacer (Ctrl/⌘ Mayús Z)")} disabled={!future.length} onclick={redo}><Redo2 size={17}/></button><span class="control-divider" aria-hidden="true"></span><button aria-label={ui.text("Mover vista")} title={ui.text("Mover vista")} aria-pressed={panMode} onclick={()=>panMode=!panMode}><Hand size={18}/></button><button aria-label={ui.text("Alejar mapa")} title={ui.text("Alejar")} disabled={!cameraReady||zoomLevel<=.65} onclick={()=>zoom(-.15)}><Minus size={18}/></button><output aria-label={ui.text("Nivel de zoom")}>{Math.round(zoomLevel*100)}%</output><button aria-label={ui.text("Acercar mapa")} title={ui.text("Acercar")} disabled={!cameraReady||zoomLevel>=3} onclick={()=>zoom(.15)}><Plus size={18}/></button><button aria-label={ui.text("Ajustar mapa a la vista")} title={ui.text("Ajustar mapa a la vista")} disabled={!cameraReady} onclick={fitMap}><Scan size={18}/></button></div>{:else}<div class="board-history"><button aria-label={ui.text("Deshacer")} disabled={!history.length} onclick={undo}><Undo2 size={17}/></button><button aria-label={ui.text("Rehacer")} disabled={!future.length} onclick={redo}><Redo2 size={17}/></button></div>{/if}<div class="editor-actions"><button disabled={!graphicsReady||!!chatEditing||saving||openingGame||playerChanging} aria-busy={saving&&!openingGame} aria-label={saving&&!openingGame?ui.text("Guardando aventura"):ui.text("Guardar")} onclick={persist}>{#if saving&&!openingGame}<LoaderCircle size={17} class="save-spinner"/>{:else}<Check size={17}/>{/if}<span>{saving&&!openingGame?ui.text("Guardando…"):ui.text("Guardar")}</span></button><button class="save-play" disabled={!graphicsReady||!!chatEditing||saving||openingGame||playerChanging} aria-busy={openingGame} aria-label={openingGame?(saving?ui.text("Guardando aventura"):ui.text("Abriendo aventura")):ui.text("Guardar y jugar")} onclick={playSaved}>{#if openingGame}<LoaderCircle size={17} class="save-spinner"/>{:else}<Play size={17}/>{/if}<span>{openingGame?(saving?ui.text("Guardando…"):ui.text("Abriendo…")):ui.text("Guardar y jugar")}</span></button></div></footer>
</div>
